<script setup lang="ts">
const gameUrl = 'https://game.chtozavino.ru/'
const pourUrl = `${gameUrl}?mode=pour`
const title = 'Wine&Dine Merge — маленькое бистро, большая история вкуса'
const description = 'Собирайте блюда, подбирайте вино и практикуйте подачу в Wine&Dine Merge. Уютная игра в браузере с путешествием по винным регионам России.'
useSeoMeta({ title, description, ogType: 'website', ogTitle: title, ogDescription: description, ogUrl: 'https://chtozavino.ru/game', twitterTitle: title, twitterDescription: description })
useHead({ link: [{ rel: 'canonical', href: 'https://chtozavino.ru/game' }] })

const regions = [
  { id: 'rostov', name: 'Ростовская область', caption: 'ПЕРВАЯ ОСТАНОВКА', title: 'Начните на берегах Дона.', copy: 'Первый гость, первый заказ и первые сочетания. Освойтесь в бистро, приготовьте блюдо и подайте к нему вино.', menu: 'Кубанский борщ · Курица с зеленью' },
  { id: 'krasnodar', name: 'Краснодарский край', caption: 'ДАЛЬШЕ ПО МАРШРУТУ', title: 'К южному солнцу и новым вкусам.', copy: 'Меняется пейзаж за окном, а вместе с ним — меню. Продолжайте знакомство со стилями вина и встречайте следующих гостей.', menu: 'Южное овощное рагу · Мидии в томатном соусе' },
  { id: 'dagestan', name: 'Дагестан', caption: 'НОВАЯ ГЛАВА ПУТЕШЕСТВИЯ', title: 'Там, где горы встречают море.', copy: 'Ещё одно бистро, другой вид за окном и блюда из игрового меню региона. Попробуйте новые сочетания и вернитесь к любимым урокам.', menu: 'Дагестанский хинкал · Чуду с сыром' },
]
const regionIndex = ref(0)
const selectedRegion = computed(() => regions[regionIndex.value]!)
function moveRegion(event: KeyboardEvent) {
  if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return
  event.preventDefault()
  regionIndex.value = event.key === 'Home' ? 0 : event.key === 'End' ? regions.length - 1 : (regionIndex.value + (event.key === 'ArrowRight' ? 1 : -1) + regions.length) % regions.length
  nextTick(() => document.getElementById(`region-tab-${selectedRegion.value.id}`)?.focus())
}
const questions = [
  { question: 'Нужно что-то скачивать?', answer: 'Можно сразу играть в браузере на телефоне или компьютере. Установка не обязательна. При желании игру можно добавить на главный экран.' },
  { question: 'Нужно разбираться в вине?', answer: 'Начните с первого заказа: игра знакомит с ингредиентами, выбором вина, бокалом и подачей. После обслуживания гостя можно посмотреть объяснение каждого результата.' },
  { question: 'Где сохраняется прогресс?', answer: 'Автоматически в браузере на этом устройстве. Вернитесь в тот же браузер, чтобы продолжить. Между устройствами прогресс не синхронизируется; очистка данных сайта может удалить сохранение.' },
  { question: 'Можно потренировать только налив?', answer: 'Да. Отдельная тренировка сразу открывает бокал и бутылку. Она не меняет прогресс основного путешествия.' },
  { question: 'Это курс сомелье?', answer: 'Это учебный игровой прототип. Сочетания и правила подачи упрощены и пока не прошли экспертную проверку. Игра предлагает практические примеры, а не универсальные рекомендации.' },
]
</script>

